"""Dependency-free, deterministic static Pages build; committed HTML works without JS."""
import json, csv, io
from pathlib import Path
from html import escape as e
ROOT=Path(__file__).resolve().parents[1]
def load(n): return json.loads((ROOT/'data'/n).read_text())
rows=load('events.json'); sources=load('sources.json'); findings=load('review.json')
nav=[('index.html','Overview'),('weekly.html','Weekly'),('monthly.html','Monthly'),('annual.html','Annual'),('special.html','Special events'),('markets.html','Markets & food'),('museums.html','Museums & science'),('culture.html','Festivals & culture'),('community.html','Community & outdoors'),('review.html','Flagged for Review'),('sources.html','Sources & method')]
def link(s):
 x=sources[s]; return f'<a href="{e(x["url"])}" rel="noreferrer">{e(x["publisher"])} ↗</a>'
def table(rs):
 out='<div class="tools"><label>Search this table <input type="search" id="search" placeholder="Event, venue, or schedule…"></label><label>Recurrence <select id="kind"><option value="">All types</option>'+''.join(f'<option>{x}</option>' for x in ['Weekly','Monthly','Annual','Special'])+'</select></label><button id="reset" type="button">Reset</button><span id="count" role="status">'+str(len(rs))+' entries</span></div><div class="table-wrap"><table id="events"><caption>Official-source inventory · blank cells are unverified · times as published by organizer</caption><thead><tr>'+''.join(f'<th scope="col">{h}</th>' for h in ['Event / category','Type','Date or recurrence','Time','SF venue','Admission','Evidence / review'])+'</tr></thead><tbody>'
 for r in rs:
  review='<details><summary>'+str(len(r['flags']))+' review notes</summary><ul>'+''.join('<li>'+e(f)+'</li>' for f in r['flags'])+'</ul></details>' if r['flags'] else '<span class="badge">Listed fields checked</span>'
  out+=f'<tr id="{r["id"]}" data-kind="{r["kind"]}"><th scope="row">{e(r["name"])}<small>{e(r["category"])}</small>'+('<small>Occurrence of After Dark; not a separate series</small>' if r['parent'] else '')+'</th>'+''.join('<td>'+e(r[k])+'</td>' for k in ['kind','schedule','time','venue','price'])+'<td>'+''.join('<div>'+link(s)+'</div>' for s in r['sources'])+f'<a class="evidence" href="sources.html#event-{r["id"]}">Row evidence</a>'+review+('<p>'+e(r['notes'])+'</p>' if r['notes'] else '')+'</td></tr>'
 return out+'</tbody></table></div><p id="empty" hidden>No matching entries. Try another search or reset the filters.</p>'
def page(file,title,desc,body):
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Official-source San Francisco events inventory with transparent verification and review notes."><title>'+e(title)+' · SF Events</title><link rel="stylesheet" href="assets/style.css"><script defer src="assets/app.js"></script></head><body><a class="skip" href="#main">Skip to content</a><aside><a class="brand" href="index.html"><span class="logo">SF</span> events<span class="dot">.</span></a><p class="eyebrow">CITY EVENT OBSERVATORY</p><nav aria-label="Main navigation">'+''.join(f'<a href="{f}"'+(' aria-current="page"' if f==file else '')+'>'+label+'</a>' for f,label in nav)+'</nav><div class="sidebar-note">SAN FRANCISCO ONLY<br>Official sources. Open evidence.<br><b>Research snapshot</b><br>18 October 2026</div></aside><main id="main"><header><span>SF EVENTS / RESEARCH DIRECTORY</span><a href="data/events.csv" download>Download CSV ↓</a></header><div class="heading"><p class="eyebrow">EXPLORE YOUR CITY, WITH EVIDENCE</p><h1>'+e(title)+'</h1><p>'+e(desc)+'</p></div>'+body+'<footer>Independent research directory, not an official City website. Schedules may change; check the organizer before attending. <a href="sources.html">Method & limitations</a> · <a href="https://github.com/buffedlizard55-lab/MaltaProj5">Repository ↗</a></footer></main></body></html>'
 (ROOT/file).write_text(html)
n=len(rows); series=sum(not r['parent'] for r in rows); flags=sum(bool(r['flags']) for r in rows)
stats='<section class="stats" aria-label="Inventory statistics">'+''.join(f'<article><span>{label}</span><strong>{value}</strong><small>{note}</small></article>' for label,value,note in [('Inventory entries',n,'Includes 8 dated After Dark themes'),('Series / standalone entries',series,'Dated themes not double-counted'),('Weekly series',sum(r['kind']=='Weekly' for r in rows),'Exceptions preserved'),('Rows needing review',flags,'Includes blank unconfirmed fields')])+'</section>'
notice='<div class="notice"><b>A transparent inventory, not an exhaustive calendar.</b> Checked 18 October 2026. Coverage remains incomplete; dates range from October 2026 to announced 2027 editions. Undated-year listings are labeled. Blank cells mean unverified, not free or not applicable. <a href="review.html">See coverage gaps and flags →</a></div>'
page('index.html','San Francisco, in events.','Discover recurring gatherings and special occasions—organized, source-linked, and honest about what is still unknown.',stats+notice+'<section class="intro"><h2>A rhythm for every kind of day</h2><p>Weekly routines, monthly gatherings, annual celebrations, and dated special programs. Categories are editorial groupings, not organizer claims.</p><div class="cards">'+''.join(f'<a href="{f}"><span>{label}</span><strong>{sum(r["kind"]==kind for r in rows):02d}</strong><small>Browse entries →</small></a>' for f,label,kind in [('weekly.html','Every week','Weekly'),('monthly.html','Every month','Monthly'),('annual.html','Every year','Annual'),('special.html','Special programs','Special')])+'</div></section><h2>All inventory entries</h2>'+table(rows))
for kind in ['Weekly','Monthly','Annual','Special']:
 file=kind.lower()+'.html'; title=kind+' events'
 page(file,title,'Recurring annual events remain separate from weekly routines. Special means a dated program or edition, not proof it never repeats.',notice+table([r for r in rows if r['kind']==kind]))
for file,cat in [('markets.html','Markets & food'),('museums.html','Museums & science'),('culture.html','Festivals & culture'),('community.html','Community & outdoors')]:
 page(file,cat,'Browse the inventory by category. Follow each official source and row evidence for details and limitations.',table([r for r in rows if r['category']==cat]))
body='<h2>Research findings & coverage gaps</h2><div class="table-wrap"><table><caption>Unresolved findings do not block publication; these are not confirmed upcoming event rows.</caption><thead><tr><th>Finding</th><th>Review detail</th><th>Official sources</th></tr></thead><tbody>'
for f in findings:
 body+='<tr><th scope="row">'+e(f['title'])+'</th><td>'+e(f['detail'])+'</td><td>'+''.join(link(s)+'<br>' for s in f.get('sources',[]))+''.join('<a href="'+e(u)+'">Reference / official site ↗</a><br>' for u in f.get('urls',[]))+'</td></tr>'
body+='</tbody></table></div><h2>Entry-level review queue</h2>'+table([r for r in rows if r['flags']])
page('review.html','Flagged for Review','Unconfirmed values are blank. Source conflicts, missing years, admission gaps, and incomplete coverage are visible here—not silently resolved.',body)
body='''<section class="prose"><h2>Verification rules</h2><ol><li>Only organizer, venue, museum or municipal pages supply admitted facts. Third-party calendars were used for discovery only, never as row evidence.</li><li>Read official pages on 18 October 2026; transcribe supported event names, schedules, times, venues and admission restrictions. Keep excerpts below for audit. Excerpts are selected transcriptions, not complete archived pages.</li><li>Weekly, monthly and annual classifications require explicit recurrence language. Special is an editorial bucket for dated programs when recurrence is not established; it does not mean one-time only.</li><li>Preserve dates as published. Do not generate next occurrences or assign years from neighboring listings. Do not call a recurring pattern a confirmed future instance.</li><li>Only San Francisco venues are admitted. Candidates with uncertain city boundaries stay in review. No nearby Bay Area cities or online-only programs are included.</li><li>Blank schedule, time, venue or admission fields are flagged unverified. A source link verifies only the facts it actually states. A blank admission field never means free.</li></ol><h2>Analysis & limitations</h2><p>This snapshot is not a full list of all SF events. There is no citywide completeness denominator. Museum and market programs are overrepresented; sports, library programs, theatre, civic meetings, nightlife and small neighborhood events are undercovered. No claim is made about popularity, attendance, total event counts citywide, or current ticket availability.</p><p>Eight After Dark theme rows are occurrences of one weekly series. Counts distinguish inventory rows from series/standalone entries. One theme is explicitly annual and is classified accordingly. Annual and special categories therefore describe both series and editions; do not sum counts as unique gatherings.</p><p>No automatic fact-verification or ongoing refresh is claimed. CI checks data structure, evidence references, and local links; it cannot establish factual truth. Official pages were successfully read at research time except the two explicitly failed candidates. External availability may change; it is not continuously monitored.</p></section><h2>Official-source register</h2>'''
for id,s in sources.items():
 body+=f'<article class="source" id="source-{id}"><h3>{e(s["publisher"])}</h3>{link(id)}<p>Checked {s["checked"]} · {e(s["method"])}</p><blockquote>{e(s["excerpt"])}</blockquote></article>'
body+='<h2>Row-by-row evidence ledger</h2>'
for r in rows:
 body+=f'<article class="source" id="event-{r["id"]}"><h3>{e(r["name"])}</h3><dl>'+''.join(f'<dt>{e(k)}</dt><dd>{e(v)} · '+', '.join(f'<a href="#source-{s}">{e(sources[s]["publisher"])}</a>' for s in r['evidence'].get(k,[]))+'</dd>' for k,v in r.items() if k in ['name','schedule','time','venue','price'] and v)+'</dl><p>Unverified / review: '+e('; '.join(r['flags']) or 'No missing tracked fields.')+'</p></article>'
page('sources.html','Sources & methodology','Every inventory row links to official pages. This ledger records what was checked, the supporting excerpts, and what remains unresolved.',body)
f=io.StringIO(); w=csv.writer(f); w.writerow(['id','name','category','kind','schedule','time','venue','price','source_urls','checked','parent','review'])
for r in rows:w.writerow([r[k] for k in ['id','name','category','kind','schedule','time','venue','price']]+[' | '.join(sources[s]['url'] for s in r['sources']),'2026-10-18',r['parent'],' | '.join(r['flags'])])
(ROOT/'data/events.csv').write_text(f.getvalue())
print(f'Built {len(nav)} pages, {n} rows, {len(sources)} official-source records.')
